<?php
namespace App\Actions\Inventory; use App\Models\Purchase; use App\Models\User; use Illuminate\Support\Facades\DB; use Illuminate\Validation\ValidationException;
class RecordPurchasePaymentAction { public function handle(Purchase $purchase, User $user, int $amount, string $method='cash', ?string $reference=null): Purchase { if ($amount < 1) throw ValidationException::withMessages(['amount'=>'Nominal pembayaran harus lebih dari nol.']); return DB::transaction(function () use ($purchase,$user,$amount,$method,$reference) { $purchase=Purchase::query()->lockForUpdate()->findOrFail($purchase->id); $remaining=$purchase->grand_total-$purchase->paid_total; if ($amount>$remaining) throw ValidationException::withMessages(['amount'=>'Nominal melebihi sisa hutang.']); $purchase->payments()->create(['amount'=>$amount,'method'=>$method,'reference_number'=>$reference,'paid_at'=>now(),'received_by'=>$user->id]); $paid=$purchase->paid_total+$amount; $purchase->update(['paid_total'=>$paid,'payment_status'=>$paid >= $purchase->grand_total ? 'paid' : 'partial']); return $purchase; }); } }
